import { strict as assert } from 'node:assert';

export function withdraw(account, amount) {
  if (!Number.isInteger(amount) || amount <= 0) throw new RangeError('amount must be positive');
  const nextBalance = account.balance - amount;
  assert.ok(nextBalance >= account.floor, `invariant: ${nextBalance} < ${account.floor}`);
  account.balance = nextBalance;
}

export function invariant(condition, message) {
  if (!condition) throw new Error(`Invariant violated: ${message}`);
}

function withdraw(account, amount) {
  invariant(Number.isInteger(amount) && amount > 0, `amount ${amount}`);
  account.balance -= amount;
  invariant(account.balance >= account.floor, 'balance below floor');
}
